CREATE VIEW Vue_LabTestGarments AS 
SELECT Distinct Top 1000 * FROM (
Select Distinct Top 1000 LabTestMas.Id,RTRIM(LabTestMas.TestNo)+'/'+RTRIM(LabTestMas.Finyear) as TestNo,EntryDate,RTRIM(OrderMas.Jobno)+'/'+RTRIM(OrderMas.Finyear) + '->' + RTRIM(OrderMas.BuyOrdNo) as OrderNo,LabTestMas.
StyleNo,Mas_Exporter.ExporterName,Case When LabTestMas.Grp='G' Then 'Garments' Else Case When LabTestMas.Grp='B' Then 'Bit' else Case When LabTestMas.Grp='A' Then 'Accessories' Else Case When LabTestMas.Grp='Y' Then 'Yarn Dyeing' End End End End as Grp,LabTestGrpMas.Slno,Case When  LabTestGrpMas.G_SampleType=0 Then 'Sample'  Else 'Random' End As SampleType,Case When LabTestGrpMas.Status='P' Then 'Pass' Else 'Fail' End As Status,Mas_Season.SeasDesc,IsNUll(Mas_Size.SizeDesc,'') as SizeDesc,IsNull(G_Mas_Color.ColorDesc,'') as G_ColorDEsc,IsNull(G_BWGSM,0) as G_BWGSM,IsNull(G_AWGSM,0) as G_AWGSM,IsNull(G_ReqdGSM,0) as G_ReqdGSM,IsNull(G_Fabric.Fabdesc,'') as G_FabDEsc,IsNull(B_Mas_Color.ColorDesc,'') as B_ColorDesc,IsNull(B_Mas_Fabric.Fabdesc,'') as B_FabDesc,IsNull(B_Mas_DEsign.DesignDesc,'') as B_DesignDesc,IsNull(B_LotNo,'') as B_LotNo,IsNull(B_BWGSM,0) as B_BWGSM,IsNull(B_AWGSM,0) as B_AWGSM,IsNull(B_Dia1,0)B_Dia1,IsNull(B_Dia2,0)B_Dia2,IsNull(B_Dia3,0)B_Dia3,IsNUll(B_BW1,0)B_BW1,IsNull(B_BW2,0)B_BW2,IsNUll(B_BW3,0)B_BW3,IsNull(B_AW1,0)B_AW1,IsNull(B_AW2,0)B_AW2,IsNull(B_AW3,0)B_AW3,IsNull(A_Mas_Acc.Acc_Descr,'') as Acc_Descr,IsNull(A_Mas_Color.ColorDesc,'') as A_ColorDEsc,IsNull(Y_Mas_Color.ColorDesc,'') as Y_ColorDEsc,Mas_Count.CountName,Case When LabTestGrpMas.DryType='F' Then 'Flat Dry' Else Case When LabTestGrpMas.DryType='T' Then 'Tumble Dry' Else 'LineDry' End End as DryType,Mas_LabTestParameters.Parameter,Mas_LabTestStages.TestName,LabTestGrpDet.Value as Value ,LabTestGrpDet.Remarks as DtlRemarks,LabTestMas.Remarks,Mas_LabTestParameters.IndexNo ,Mas_LabTestStages.IndexValue,isnull(Mas_Buyer.BuyerName,'') BuyerName, isnull(B_ReqdGSM,0) B_ReqdGSM   From LabTestMas  INNER JOIN OrderMas ON LabTestMas.OrdId=OrderMas.OrdId  INNER JOIN Mas_Exporter ON Mas_Exporter
.ExpID=LabTestMas.Coycode INNER JOIN Mas_Season ON Mas_Season.SeasID=OrderMas.Season INNER JOIN LabTestGrpMas ON LabTestGrpMas.Id=LabTestMas.Id LEFT OUTER JOIN Mas_Size ON Mas_Size.SizeID=LabTestGrpMas.G_SizeId LEFT OUTER JOIN Mas_Color G_Mas_Color ON G_Mas_Color.ColID=LabTestGrpMas.G_Clr LEFT OUTER JOIN Mas_Fabric G_Fabric ON G_Fabric.FabID=LabTestGrpMas.G_FabId LEFT OUTER JOIN Mas_Color B_Mas_Color ON B_Mas_Color.ColID=LabTestGrpMas.B_Clr LEFT OUTER JOIN Mas_Fabric B_Mas_Fabric  ON B_Mas_Fabric.FabId=LabTestGrpMas.B_FabId LEFT OUTER JOIN Mas_Design B_Mas_DEsign ON B_Mas_DEsign.DesignId=LabTestGrpMas.B_DesignId LEFT OUTER JOIN Mas_Acc A_Mas_Acc ON A_Mas_Acc.ID=LabTestGrpMas.A_AccTypeId LEFT OUTER JOIN Mas_Color A_Mas_Color ON A_Mas_Color.ColID=LabTestGrpMas.A_CLr LEFT OUTER JOIN Mas_Color Y_Mas_Color ON Y_Mas_Color.ColID=LabTestGrpMas.Y_Clr LEFT OUTER JOIN Mas_Count ON Mas_Count.CountID=LabTesTGrpMas.Y_Count INNER JOIN LabTestGrpDet ON LabTestGrpMas.Id=LabTestGrpDet.Id and LabTestGrpDet.Slno=LabTestGrpMas.Slno INNER JOIN Mas_LabTestParameters ON Mas_LabTestParameters.Id=LabTestGrpDet.ParameterCode INNER JOIN Mas_LabTestStages ON Mas_LabTestStages.TestCode=LabTestGrpDet.StageCode left Outer Join Mas_Buyer on Mas_Buyer.BuyerID=OrderMas.BuyerID 
 
UNION
Select Distinct Top 1000 LabTestMas.Id,RTRIM(LabTestMas.TestNo)+'/'+RTRIM(LabTestMas.Finyear) as TestNo,EntryDate,RTRIM(OrderMas.Jobno)+'/'+RTRIM(OrderMas.Finyear) + '->' + RTRIM(OrderMas.BuyOrdNo) as OrderNo,LabTestMas.
StyleNo,Mas_Exporter.ExporterName,Case When LabTestMas.Grp='G' Then 'Garments' Else Case When LabTestMas.Grp='B' Then 'Bit' else Case When LabTestMas.Grp='A' Then 'Accessories' Else Case When LabTestMas.Grp='Y' Then 'Yarn Dyeing' End End End End as Grp,LabTestGrpMas.Slno,Case When  LabTestGrpMas.G_SampleType=0 Then 'Sample'  Else 'Random' End As SampleType,Case When LabTestGrpMas.Status='P' Then 'Pass' Else 'Fail' End As Status,Mas_Season.SeasDesc,IsNUll(Mas_Size.SizeDesc,'') as SizeDesc,IsNull(G_Mas_Color.ColorDesc,'') as G_ColorDEsc,IsNull(G_BWGSM,0) as G_BWGSM,IsNull(G_AWGSM,0) as G_AWGSM,IsNull(G_ReqdGSM,0) as G_ReqdGSM,IsNull(G_Fabric.Fabdesc,'') as G_FabDEsc,IsNull(B_Mas_Color.ColorDesc,'') as B_ColorDesc,IsNull(B_Mas_Fabric.Fabdesc,'') as B_FabDesc,IsNull(B_Mas_DEsign.DesignDesc,'') as B_DesignDesc,IsNull(B_LotNo,'') as B_LotNo,IsNull(B_BWGSM,0) as B_BWGSM,IsNull(B_AWGSM,0) as B_AWGSM,IsNull(B_Dia1,0)B_Dia1,IsNull(B_Dia2,0)B_Dia2,IsNull(B_Dia3,0)B_Dia3,IsNUll(B_BW1,0)B_BW1,IsNull(B_BW2,0)B_BW2,IsNUll(B_BW3,0)B_BW3,IsNull(B_AW1,0)B_AW1,IsNull(B_AW2,0)B_AW2,IsNull(B_AW3,0)B_AW3,IsNull(A_Mas_Acc.Acc_Descr,'') as Acc_Descr,IsNull(A_Mas_Color.ColorDesc,'') as A_ColorDEsc,IsNull(Y_Mas_Color.ColorDesc,'') as Y_ColorDEsc,Mas_Count.CountName,Case When LabTestGrpMas.DryType='F' Then 'Flat Dry' Else Case When LabTestGrpMas.DryType='T' Then 'Tumble Dry' Else 'LineDry' End End as DryType,'Status' as Parameter,TestName ,

Case When Upper(LabTestGrpDet.Remarks) ='PASS' then 1 Else Case When  
Upper(LabTestGrpDet.Remarks) ='FAIL' then 0 ELSE 0 END END as Value ,LabTestGrpDet.Remarks as DtlRemarks,LabTestMas.Remarks,900 as IndexNo ,Mas_LabTestStages.IndexValue,isnull(Mas_Buyer.BuyerName,'') BuyerName, isnull(B_ReqdGSM,0) B_ReqdGSM   From LabTestMas  INNER JOIN OrderMas ON LabTestMas.OrdId=OrderMas.OrdId  INNER JOIN Mas_Exporter ON Mas_Exporter
.ExpID=LabTestMas.Coycode INNER JOIN Mas_Season ON Mas_Season.SeasID=OrderMas.Season INNER JOIN LabTestGrpMas ON LabTestGrpMas.Id=LabTestMas.Id LEFT OUTER JOIN Mas_Size ON Mas_Size.SizeID=LabTestGrpMas.G_SizeId LEFT OUTER JOIN Mas_Color G_Mas_Color ON G_Mas_Color.ColID=LabTestGrpMas.G_Clr LEFT OUTER JOIN Mas_Fabric G_Fabric ON G_Fabric.FabID=LabTestGrpMas.G_FabId LEFT OUTER JOIN Mas_Color B_Mas_Color ON B_Mas_Color.ColID=LabTestGrpMas.B_Clr LEFT OUTER JOIN Mas_Fabric B_Mas_Fabric  ON B_Mas_Fabric.FabId=LabTestGrpMas.B_FabId LEFT OUTER JOIN Mas_Design B_Mas_DEsign ON B_Mas_DEsign.DesignId=LabTestGrpMas.B_DesignId LEFT OUTER JOIN Mas_Acc A_Mas_Acc ON A_Mas_Acc.ID=LabTestGrpMas.A_AccTypeId LEFT OUTER JOIN Mas_Color A_Mas_Color ON A_Mas_Color.ColID=LabTestGrpMas.A_CLr LEFT OUTER JOIN Mas_Color Y_Mas_Color ON Y_Mas_Color.ColID=LabTestGrpMas.Y_Clr LEFT OUTER JOIN Mas_Count ON Mas_Count.CountID=LabTesTGrpMas.Y_Count INNER JOIN LabTestGrpDet ON LabTestGrpMas.Id=LabTestGrpDet.Id and LabTestGrpDet.Slno=LabTestGrpMas.Slno INNER JOIN Mas_LabTestParameters ON Mas_LabTestParameters.Id=LabTestGrpDet.ParameterCode INNER JOIN Mas_LabTestStages ON Mas_LabTestStages.TestCode=LabTestGrpDet.StageCode left Outer Join Mas_Buyer on Mas_Buyer.BuyerID=OrderMas.BuyerID  ) X Order BY X.IndexNo,X.IndexValue